(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const report = () => JSON.stringify({
    url: location.href,
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/invalid|incorrect|wrong|expired|failed|not found|mismatch/i.test(t) && t.length<90).slice(0,5)),
    pinVisible: Array.from(document.querySelectorAll('input[type=text],input[type=password]')).filter(i=>i.offsetParent!==null && (i.maxLength===4 || /pin/i.test(i.id||''))).length,
    otpVisible: Array.from(document.querySelectorAll('input[type=number]')).filter(i=>i.offsetParent!==null).length
  });
  const boxes = Array.from(document.querySelectorAll('input[type=number]')).filter(i => /^(first|second|third|fourth|fifth|sixth)$/.test(i.id||'') && i.offsetParent !== null);
  if (!boxes.length) return JSON.stringify({stage:'noVisibleBoxes', ...JSON.parse(report())});
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  const digits = '978963';
  for (let i = 0; i < boxes.length; i++) {
    setter.call(boxes[i], i < digits.length ? digits[i] : '');
    boxes[i].dispatchEvent(new Event('input', {bubbles:true}));
    boxes[i].dispatchEvent(new Event('change', {bubbles:true}));
  }
  await sleep(300);
  let btn = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test((b.innerText||'').replace(/\s+/g,' ')) && b.offsetParent !== null);
  if (!btn) btn = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*OTP/i.test((b.innerText||'').replace(/\s+/g,' ')));
  if (btn) btn.click();
  await sleep(8000);
  const pinInput = Array.from(document.querySelectorAll('input[type=text],input[type=password]')).find(i => i.offsetParent!==null && i.maxLength===4);
  if (pinInput) {
    setter.call(pinInput, '8751');
    pinInput.dispatchEvent(new Event('input', {bubbles:true}));
    pinInput.dispatchEvent(new Event('change', {bubbles:true}));
    await sleep(300);
    const pb = Array.from(document.querySelectorAll('button')).find(b => /Confirm\s*PIN/i.test((b.innerText||'').replace(/\s+/g,' ')));
    if (pb) pb.click();
    await sleep(8000);
  }
  return JSON.stringify({stage:'done', ...JSON.parse(report())});
})()
